<script setup>
import AdminMenuButton from './AdminMenuButton.vue'
import AdminTabs from './AdminTabs.vue'
import { ref, inject, computed, onMounted, onBeforeUnmount, nextTick } from 'vue'
import {sameContent,scheduleDraft} from '@/utils/adminDrafts'
import AdminIcon from './AdminIcon.vue'
import {useRoute} from 'vue-router'
import { onBeforeRouteLeave } from 'vue-router'
import { adminRequest, formatDate } from '@/utils/adminApi'
const navigation=inject('adminOpenNavigation'),confirm=inject('adminConfirm')
const runs=ref([]),schedules=ref([]),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(true),selected=ref(null),modal=ref(null)
const labels={all:'全量同步',favorites:'收藏同步',daily:'每日搜索',translations:'标签翻译'}
const states={queued:'排队中',in_progress:'执行中',success:'成功',failure:'失败',cancelled:'已取消',timed_out:'超时',completed:'已完成'}
const filter=ref('all'),visible=computed(()=>runs.value.filter(r=>filter.value==='all'||r.status===filter.value||r.conclusion===filter.value))
const route=useRoute(),tab=ref('runs'),events=ref([]),logError=ref(''),follow=ref(true),live=ref(true),logLevel=ref('all'),logBody=ref(null),now=ref(Date.now())
const filteredEvents=computed(()=>events.value.filter(e=>logLevel.value==='all'||e.level!=='info'))
const active=computed(()=>runs.value.filter(r=>r.status!=='completed'))
const failed=computed(()=>runs.value.filter(r=>['failure','timed_out'].includes(r.conclusion)))
let timer,clockTimer,polling=false,detailLoading=false
function elapsed(run){const end=run.status==='completed'?new Date(run.updatedAt).getTime():now.value;const seconds=Math.max(0,Math.floor((end-new Date(run.createdAt).getTime())/1000));return seconds<60?seconds+' 秒':Math.floor(seconds/60)+' 分 '+seconds%60+' 秒'}
function percent(step){return step.status==='success'?100:step.progress.totalBatches?Math.min(100,Math.round((step.progress.completedBatches||0)/step.progress.totalBatches*100)):null}
function time(value){return new Date(value).toLocaleTimeString('zh-CN',{hour12:false})}
async function details(run){selected.value=run;events.value=[];logError.value='';live.value=true;modal.value.showModal();await refreshDetails()}
async function refreshDetails(){if(!selected.value||detailLoading)return;detailLoading=true;const id=selected.value.id;try{const result=await adminRequest('job-detail',{runId:id,after:events.value.at(-1)?.id||0});if(selected.value?.id!==id)return;selected.value=result.run;events.value=[...events.value,...result.events].slice(-2000);logError.value='';await nextTick();if(follow.value&&logBody.value)logBody.value.scrollTop=logBody.value.scrollHeight}catch(e){logError.value=e.message}finally{detailLoading=false}}
async function load(){try{const [jobs,config]=await Promise.all([adminRequest('runs'),adminRequest('schedules')]);runs.value=jobs.runs;schedules.value=config.items.map(s=>{const draft=schedules.value.find(old=>old.kind===s.kind&&scheduleDirty(old));return draft||{...s,enabled:Boolean(s.enabled),original:JSON.stringify({enabled:Boolean(s.enabled),hour:s.hour,minute:s.minute,timezone:s.timezone})}});if(selected.value)selected.value=runs.value.find(r=>r.id===selected.value.id)||selected.value}catch(e){error.value=e.message}finally{loading.value=false}}
async function perform(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function dispatch(kind){if(!await confirm({title:`启动${labels[kind]}？`,description:'使用当前已保存的配置加入后台队列，成功后直接更新公开数据。',confirmLabel:'启动任务'}))return;await perform(async()=>{const result=await adminRequest('dispatch',{workflow:kind});notice.value=`任务 #${result.id} 已排队。`})}
async function all(){if(!await confirm({title:'分别同步全部数据？',description:'收藏、标签翻译和每日搜索将作为三个独立任务执行，各自成功后生效。',confirmLabel:'启动三个任务'}))return;await perform(async()=>{await adminRequest('dispatch-all');notice.value='三个同步任务已排队。'})}
async function cancel(run){if(!await confirm({title:'取消此任务？',description:'正在抓取的任务会终止，尚未发布的数据不会覆盖现有结果。',confirmLabel:'取消任务',danger:true}))return;await perform(async()=>{await adminRequest('job-cancel',{runId:run.id});notice.value='取消请求已提交。'})}
async function retry(run,original){if(!await confirm({title:original?'重试失败步骤？':'按当前配置重新执行？',description:original?'使用原任务的冻结配置，复用已成功步骤；原规则若已被修改，发布时仍会进行版本检查。':'全部步骤使用当前配置重新执行。',confirmLabel:original?'重试失败步骤':'重新执行'}))return;await perform(async()=>{await adminRequest('rerun',{runId:run.id,original});notice.value='任务已排队。'})}
function scheduleDirty(s){return !sameContent(JSON.parse(s.original),scheduleDraft(s))}
async function save(s){if(!scheduleDirty(s))return;await perform(async()=>{await adminRequest('schedule-save',{kind:s.kind,version:s.version,...scheduleDraft(s)});s.original=JSON.stringify({enabled:s.enabled,hour:s.hour,minute:s.minute,timezone:s.timezone});notice.value='调度已保存，worker 会在十秒内读取新配置。'})}
onMounted(async()=>{await load();if(route.query.run){const run=runs.value.find(r=>r.id===Number(route.query.run));if(run)details(run)}clockTimer=setInterval(()=>now.value=Date.now(),1000);timer=setInterval(async()=>{if(polling||busy.value||document.visibilityState!=='visible')return;polling=true;try{const result=await adminRequest('runs');runs.value=result.runs;if(selected.value&&live.value)await refreshDetails()}catch(e){error.value=e.message}finally{polling=false}},2000)})
const dirty=computed(()=>schedules.value.some(scheduleDirty))
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onBeforeRouteLeave(async()=>!dirty.value||await confirm({title:'放弃未保存的调度修改？',description:'调度必须保存后才会执行。',confirmLabel:'放弃并离开',danger:true}))
onBeforeUnmount(()=>{clearInterval(timer);clearInterval(clockTimer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><div class="a-page ops-page" :aria-busy="busy||loading">
<header class="ops-page-header"><div class="ops-header-copy"><AdminMenuButton /><span class="ops-kicker">AUTOMATION / 运行中心</span><h1>同步任务与调度</h1><p>让任务在后台推进，让每一步都清晰可见。</p></div><button class="a-button" :disabled="busy" @click="load"><AdminIcon name="refresh" :size="16"/>刷新</button></header>
<div v-if="error" class="a-alert a-alert-error" role="alert">{{error}}</div><div v-if="notice" class="a-alert a-alert-success" role="status">{{notice}}</div>
<section class="ops-command-bar"><div class="ops-live-dot" :class="{'is-running':active.length}"></div><div><strong>{{active.length?`${active.length} 个任务正在推进`:'队列空闲，随时准备执行'}}</strong><small>{{failed.length?`${failed.length} 个最近任务需要关注`:'任务成功后自动发布，抓取期间继续提供现有内容'}}</small></div><button class="a-button a-primary" :disabled="busy" @click="all"><AdminIcon name="plus" :size="16"/>分别同步全部</button></section>
<AdminTabs v-model="tab" label="任务视图" :items="[{id:'runs',label:'运行记录',icon:'tasks',count:runs.length},{id:'schedules',label:'每日调度',icon:'clock',count:schedules.filter(s=>s.enabled).length+' / '+schedules.length}]"/>
<section v-if="tab==='runs'" id="tasks-tabs-panel-runs" class="a-task-panel" role="tabpanel" aria-labelledby="tasks-tabs-runs"><div class="ops-launch-grid"><button v-for="(kind,index) in ['favorites','translations','daily']" :key="kind" class="ops-launch" :disabled="busy" @click="dispatch(kind)"><span class="ops-launch-icon"><AdminIcon :name="['gallery','translate','filter'][index]"/></span><div><strong>{{labels[kind]}}</strong><small>{{['更新收藏列表与元数据','更新标签词典和中文名称','按已保存规则获取最新结果'][index]}}</small></div><AdminIcon name="arrow" :size="18"/></button></div>
<section class="a-card ops-runs"><div class="ops-section-title"><h2>运行记录</h2><select v-model="filter" aria-label="筛选任务状态"><option value="all">全部状态</option><option value="queued">排队中</option><option value="in_progress">执行中</option><option value="failure">失败</option><option value="success">成功</option><option value="cancelled">已取消</option></select></div><article v-for="run in visible" :key="run.id" class="v2-run ops-run"><div class="ops-run-marker" :class="run.conclusion||run.status"><AdminIcon :name="run.conclusion==='success'?'check':run.conclusion==='failure'?'info':run.status==='in_progress'?'refresh':'clock'" :size="18"/></div><div class="ops-run-main"><div class="ops-section-title"><div><button class="ops-run-title" @click="details(run)">{{run.name}} <small>#{{run.id}}</small></button><p class="ops-muted">{{formatDate(run.createdAt)}} · 耗时 {{elapsed(run)}}<span v-if="run.parentId"> · 重试自 #{{run.parentId}}</span></p></div><span class="ops-state" :class="run.conclusion||run.status">{{run.cancelRequested&&run.status==='in_progress'?'正在取消':states[run.conclusion||run.status]}}</span></div><p class="ops-run-summary">{{run.summary||'等待 worker 领取'}}</p><div v-if="run.steps.length" class="ops-step-strip"><div v-for="step in run.steps" :key="step.name" :class="step.status"><span>{{labels[step.name]}}</span><strong>{{step.status==='success'?'已完成':step.progress.totalBatches?`${step.progress.completedBatches||0} / ${step.progress.totalBatches} 批`:step.progress.pages?`${step.progress.pages} 页`:states[step.status]}}</strong><div class="ops-progress" :class="{'is-indeterminate':percent(step)===null&&step.status==='in_progress'}"><i :style="{width:(percent(step)||0)+'%'}"/></div></div></div><div class="a-toolbar"><button class="a-button" @click="details(run)"><AdminIcon name="tasks" :size="15"/>日志与进度</button><button v-if="run.status!=='completed'" class="a-text-button" :disabled="busy||run.cancelRequested" @click="cancel(run)">取消任务</button><template v-else><button class="a-text-button" :disabled="busy" @click="retry(run,false)">按当前配置重跑</button><button v-if="run.conclusion!=='success'" class="a-text-button" :disabled="busy" @click="retry(run,true)">重试失败步骤</button></template></div></div></article><div v-if="!visible.length" class="ops-empty"><AdminIcon name="tasks" :size="36"/><h3>{{runs.length?'没有符合筛选的任务':'从一次同步开始'}}</h3><p>选择上方的数据类型，执行过程和结果会保留在这里。</p></div></section></section>
<section v-else id="tasks-tabs-panel-schedules" class="ops-schedule-section" role="tabpanel" aria-labelledby="tasks-tabs-schedules"><div class="ops-section-title"><div><h2>按你的节奏，自动更新</h2><p class="ops-muted">时间按所选时区执行。暂停调度不会取消已经排队的任务。</p></div></div><div class="ops-schedule-grid v2-schedules"><article v-for="(s,index) in schedules" :key="s.kind" :class="{'is-enabled':s.enabled}"><div class="ops-section-title"><span class="ops-launch-icon"><AdminIcon :name="s.kind==='favorites'?'gallery':s.kind==='daily'?'filter':'translate'"/></span><label class="ops-switch"><input v-model="s.enabled" type="checkbox" :disabled="busy" :aria-label="'启用'+labels[s.kind]"/><span/></label></div><h3>{{labels[s.kind]}}</h3><p class="ops-muted">{{s.enabled?'每日自动执行':'自动执行已暂停'}}</p><div class="ops-schedule-time">{{String(s.hour).padStart(2,'0')}}<span>:</span>{{String(s.minute).padStart(2,'0')}}</div><div class="v2-time"><label>时<input v-model.number="s.hour" :disabled="busy" type="number" min="0" max="23" :aria-label="labels[s.kind]+'执行小时'"/></label><label>分<input v-model.number="s.minute" :disabled="busy" type="number" min="0" max="59" :aria-label="labels[s.kind]+'执行分钟'"/></label><label>时区<select v-model="s.timezone" :disabled="busy"><option>Asia/Shanghai</option><option>UTC</option></select></label></div><div class="ops-schedule-next"><AdminIcon name="clock" :size="15"/><span>{{scheduleDirty(s)?'修改待保存，保存后计算下次时间':s.enabled?'下次：'+formatDate(s.next_run_at):'启用并保存后开始调度'}}</span></div><button class="a-button" :class="{'a-primary':scheduleDirty(s)}" :disabled="busy||!scheduleDirty(s)" @click="save(s)">{{scheduleDirty(s)?'保存调度':'已保存'}}</button></article></div></section>
<dialog ref="modal" class="a-modal ops-task-drawer" @close="selected=null"><template v-if="selected"><header class="ops-drawer-header"><div><span class="ops-kicker">TASK #{{selected.id}}</span><h2>{{selected.name}}</h2><p>{{formatDate(selected.createdAt)}} · {{elapsed(selected)}}</p></div><button class="ops-icon" aria-label="关闭任务详情" @click="modal.close()"><AdminIcon name="close"/></button></header><div class="ops-drawer-body"><div class="ops-section-title"><span class="ops-state" :class="selected.conclusion||selected.status">{{states[selected.conclusion||selected.status]}}</span><label class="ops-inline-check"><input v-model="live" type="checkbox"/>实时更新</label></div><p class="ops-run-summary">{{selected.summary||'等待执行'}}</p><div class="ops-task-stages"><article v-for="step in selected.steps" :key="step.name" :class="step.status"><AdminIcon :name="step.status==='success'?'check':'clock'" :size="18"/><div><strong>{{labels[step.name]}}</strong><p>{{step.summary||'正在处理'}}</p><small v-if="step.progress.totalGroups">分组 {{step.progress.group}} / {{step.progress.totalGroups}}</small><small v-if="step.progress.pages">已扫描 {{step.progress.pages}} 页<span v-if="step.progress.items">，累计 {{step.progress.items}} 条</span></small><small v-if="step.progress.totalBatches">元数据 {{step.progress.completedBatches||0}} / {{step.progress.totalBatches}} 批</small><div class="ops-progress" :class="{'is-indeterminate':percent(step)===null&&step.status==='in_progress'}"><i :style="{width:(percent(step)||0)+'%'}"/></div></div><span>{{states[step.status]}}</span></article></div><div class="ops-section-title ops-log-heading"><h3>执行日志 <small>{{events.length}}</small></h3><button class="a-text-button" @click="refreshDetails">刷新</button></div><div class="ops-log-tools"><select v-model="logLevel" aria-label="日志级别"><option value="all">全部事件</option><option value="warning">警告与错误</option></select><label class="ops-inline-check"><input v-model="follow" type="checkbox"/>跟随最新</label></div><p v-if="logError" class="a-alert a-alert-error">{{logError}}</p><div ref="logBody" class="ops-log" role="log" aria-label="任务执行日志" aria-live="off"><div v-for="entry in filteredEvents" :key="entry.id" :class="entry.level"><time>{{time(entry.at)}}</time><span class="ops-log-stage">{{labels[entry.stage]||({queue:'队列',backup:'备份',publish:'发布',finish:'结束'})[entry.stage]}}</span><span>{{entry.message}}</span></div><p v-if="!filteredEvents.length">{{events.length?'暂无警告或错误':selected.status==='queued'?'等待领取任务…':'该任务暂无事件记录。升级前的任务仍可查看上方步骤摘要。'}}</p></div><p class="ops-muted">保留每个任务最近 2,000 条事件。日志记录执行明细，不包含来源链接、Cookie 或服务密钥。</p><details class="ops-config-details"><summary>本次使用的规则 <span>{{selected.config.daily?.length||0}} 个分组</span></summary><article v-for="group in selected.config.daily" :key="group.name"><strong>{{group.name}}</strong><p>{{group.keyword||'不限关键词'}}</p><small>回溯 {{group.cutoffDays}} 天 · {{group.minPages||'不限'}}–{{group.maxPages||'不限'}} 页 · 评分 {{group.minRating||'不限'}}</small></article></details></div><footer class="ops-drawer-footer"><span class="ops-muted">{{live?'每 2 秒自动更新':'自动更新已暂停'}}</span><button v-if="selected.status!=='completed'" class="a-button" :disabled="busy||selected.cancelRequested" @click="cancel(selected)">取消任务</button><button v-else class="a-button" :disabled="busy" @click="retry(selected,false)">按当前配置重跑</button></footer></template></dialog>
</div></template>
